package net.civeira.phylax.features.document.themeasset.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.themeasset.domain.ThemeAsset;
import net.civeira.phylax.features.document.themeasset.domain.event.ThemeAssetEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ThemeAssetEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ThemeAssetEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ThemeAsset entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
